      hu: ["Magasfennsík", "Sivatagi ökoszisztéma", "Természetes vízforrások", "Antilop élőhely"],
      ro: ["Podiș înalt", "Ecosistem deșertic", "Surse naturale de apă", "Habitat pentru antilope"],
      en: ["High plateau", "Desert ecosystem", "Natural water sources", "Antelope habitat"],
      es: ["Meseta elevada", "Ecosistema del desierto", "Fuentes de agua naturales", "Hábitat de antílopes"],
      pt: ["Planalto elevado", "Ecossistema do deserto", "Fontes de água naturais", "Habitat de antílopes"],
      fr: ["Haut plateau", "Écosystème désertique", "Sources d'eau naturelles", "Habitat des antilopes"],
