      es: ["Kedia d'Idjil", "Ecología de montaña", "Agua temporal", "Abrevadero de fauna"],
      pt: ["Kedia d'Idjil", "Ecologia de montanha", "Água temporária", "Bebedouro de fauna"],
      fr: ["Kédia d'Idjil", "Écologie de montagne", "Eau temporaire", "Abreuvoir pour la faune"],
